package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A validated rate form: the grade, its percent with two decimals and its from-date and to-date (null when none). */
public record RateInput(String grade, BigDecimal pct, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.sheet;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads the sheet by id, starting an empty one when the id was never used. */
public class LoadOrCreateSheet {
